#!/usr/bin/env bash
# Crea etiquetas, milestones e issues del MVP de RifaFácil en el repositorio actual.
# Requiere GitHub CLI (gh) con sesión iniciada. Ejecutar dentro del repo: bash docs/crear-issues.sh
set -e
REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner)
echo "Creando en $REPO"

# Etiquetas
gh label create "ui" --color 1d76db --force >/dev/null
gh label create "datos" --color 5319e7 --force >/dev/null
gh label create "lógica" --color fbca04 --force >/dev/null
gh label create "pruebas" --color 0e8a16 --force >/dev/null
gh label create "integración" --color d93f0b --force >/dev/null
gh label create "tarea" --color cfd3d7 --force >/dev/null
gh label create "mejora" --color a2eeef --force >/dev/null

# Milestones
gh api "repos/$REPO/milestones" -f title="Fase 1 — Estructura base y navegación" -f description="Ver docs/ROADMAP.md" >/dev/null 2>&1 || true
gh api "repos/$REPO/milestones" -f title="Fase 2 — Rifas y grilla de números" -f description="Ver docs/ROADMAP.md" >/dev/null 2>&1 || true
gh api "repos/$REPO/milestones" -f title="Fase 3 — Vendedores y rendiciones" -f description="Ver docs/ROADMAP.md" >/dev/null 2>&1 || true
gh api "repos/$REPO/milestones" -f title="Fase 4 — Deudores y avisos" -f description="Ver docs/ROADMAP.md" >/dev/null 2>&1 || true
gh api "repos/$REPO/milestones" -f title="Fase 5 — Sorteo y reporte" -f description="Ver docs/ROADMAP.md" >/dev/null 2>&1 || true

# Issues
gh issue create --title "[F1-T1] Instalar dependencias y abrir la app en Expo Go" --body "$(printf 'Fase 1 — Estructura base y navegación\nHistorias: —\nEstimación: 2 h\n\nVer docs/PLANNING.md y docs/SPEC.md.\n\nCriterios:\n- [ ] Definición de terminado cumplida (lint, tipos, tests, modo avión).')" --label "tarea" --milestone "Fase 1 — Estructura base y navegación" >/dev/null
gh issue create --title "[F1-T2] Verificar creación y migración de la base" --body "$(printf 'Fase 1 — Estructura base y navegación\nHistorias: —\nEstimación: 2 h\n\nVer docs/PLANNING.md y docs/SPEC.md.\n\nCriterios:\n- [ ] Definición de terminado cumplida (lint, tipos, tests, modo avión).')" --label "datos" --milestone "Fase 1 — Estructura base y navegación" >/dev/null
gh issue create --title "[F1-T3] Definir la navegación principal" --body "$(printf 'Fase 1 — Estructura base y navegación\nHistorias: —\nEstimación: 2 h\n\nVer docs/PLANNING.md y docs/SPEC.md.\n\nCriterios:\n- [ ] Definición de terminado cumplida (lint, tipos, tests, modo avión).')" --label "ui" --milestone "Fase 1 — Estructura base y navegación" >/dev/null
gh issue create --title "[F1-T4] Aplicar tema y componente Pantalla" --body "$(printf 'Fase 1 — Estructura base y navegación\nHistorias: —\nEstimación: 2 h\n\nVer docs/PLANNING.md y docs/SPEC.md.\n\nCriterios:\n- [ ] Definición de terminado cumplida (lint, tipos, tests, modo avión).')" --label "ui" --milestone "Fase 1 — Estructura base y navegación" >/dev/null
